  "note": {
    "summary": "The email bears on NVDA and GOOGL. Tessellate Advisory Network is offering one of four seats on a small-group call with a former head of compute capacity planning at a frontier AI lab. The guest relays secondhand word that AI labs are asking for committed Google Cloud TPU capacity for 2027 inference, volume previously assumed to go to Nvidia systems.",
    "why_attention": "Attending gives the desk an early read on a possible shift in the inference mix, ahead of the Oct 27 and November reports, from someone with capacity-sourcing experience. Seats are capped at four and the sender asks for confirmation the same day. The sender stresses the report is unconfirmed and secondhand.",
    "action": "attend",
    "follow_up": "The analysts covering NVDA and GOOGL should confirm seats by 5pm on 13 October 2026, then join the call on Wednesday 7:45-8:30am ET.",
    "deadline": "2026-10-13T17:00:00",
    "sections": [
      {"quote": "their organizations are asking for committed TPU capacity from Google Cloud for 2027 inference"},
      {"quote": "He was explicit that this is secondhand."},
      {"quote": "Please confirm by 5pm today so I can hold your seats."}
    ]
  }
}
